    [CascadingParameter]
    protected Expense expense { get; set; }

    private IEnumerable<Category> categories = new List<Category>();

    [Parameter]
    public ExpenseType ExpenseType { get; set; }

    protected async override Task OnInitializedAsync()
    {
        categories = await CategoryService.GetAllCategories();

        if(expense.Id == 0)
        {
            expense.CategoryId = categories.FirstOrDefault().Id.ToString();

            expense.ExpenseType = ExpenseType;
        }

    }

    protected async Task SaveExpense()
    {
        await IExpenseService.SaveExpense(expense);
        ClearExpense();

        expense.SelectedExpenseChanged(expense);
    }

    protected string GetCancelButtonStyle()
    {
        return expense.Id == 0 ? "display:None" : "";
    }

    public void Cancel()
    {
        ClearExpense();
    }

    private void ClearExpense()
    {
        expense.Id = 0;
        expense.Amount = 0;
        expense.TransactionDate = DateTime.MinValue;
        expense.CategoryId = categories.FirstOrDefault().Id.ToString();
        expense.ExpenseType = ExpenseType;
    }

    protected async Task DeleteExpense()
    {
        //metodo java script para confirmar
        bool Confirmed = await JSRuntime.InvokeAsync<bool>("confirm", "Are yue sure?");
        if(Confirmed == true)
        {
            await IExpenseService.DeleteExpense(expense.Id);
            expense.SelectedExpenseChanged(expense);
            ClearExpense();
        }
    }

